  {
   "cell_type": "markdown",
   "id": "d6819619-4d26-4f5e-87a8-967a1c359005",
   "metadata": {
    "collapsed": True,
    "jupyter": {
     "outputs_hidden": True
    }
   },
   "source": [
    "#Chennel margine analysis 1) compute : net profit per channel ,margine percentage per channel. 2) compare absolute profit VS margine efficiency\n",
    "\n",
    "  \n",
    "\n",
    "\n",
    "# Calculate overall KPIs\n",
    "\n",
    "total_revenue = (\n",
    "    df['InStoreRevenue'].sum()\n",
    "    + df['UberEatsRevenue'].sum()\n",
    "    + df['DoorDashRevenue'].sum()\n",
    "    + df['SelfDeliveryRevenue'].sum()\n",
    ")\n",
    "\n",
    "total_profit = (\n",
    "    df['InStoreNetProfit'].sum()\n",
    "    + df['UberEatsNetProfit'].sum()\n",
    "    + df['DoorDashNetProfit'].sum()\n",
    "    + df['SelfDeliveryNetProfit'].sum()\n",
    ")\n",
    "\n",
    "total_orders = (\n",
    "    df['InStoreOrders'].sum()\n",
    "    + df['UberEatsOrders'].sum()\n",
    "    + df['DoorDashOrders'].sum()\n",
    "    + df['SelfDeliveryOrders'].sum()\n",
    ")\n",
    "\n",
    "profit_margin = (total_profit / total_revenue) * 100 if total_revenue else 0\n",
    "\n",
    "print(\"Total Revenue:\", round(total_revenue, 2))\n",
    "print(\"Total Net Profit:\", round(total_profit, 2))\n",
    "print(\"Total Orders:\", total_orders)\n",
    "print(\"Overall Profit Margin:\", round(profit_margin, 2), \"%\")"
   ]
  },
